INSERT INTO entity_citations (citation_id,entity_id,source_id,work_title,locus,quote,translator,translation_year,source_url,original_text_url,evidence_grade,evidence_note,needs_review,review_reason,verified_on,verify_method,display_order) VALUES
('CIT_NOR_ANGRBODA_PROSE_','ENT_NOR_ANGRBODA','SRC_PROSE_EDDA','Snorri Sturluson, Prose Edda','Snorri Sturluson, Prose Edda','A giantess in Jotunheim, hight Angerboda. With her he begat three children. The first was the Fenris-wolf; the second, Jormungand, that is, the Midgard-serpent, and the third, Hel.','Rasmus B. Anderson',1880,'https://www.gutenberg.org/ebooks/18947',NULL,'primary-verbatim',NULL,true,'English translation (Anderson, The Younger Edda) located by name within the work (not exact chapter); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NOR_AUDHUMLA_PROSE_','ENT_NOR_AUDHUMLA','SRC_PROSE_EDDA','Snorri Sturluson, Prose Edda','Snorri Sturluson, Prose Edda','Then said Ganglere: Where did Ymer dwell, and on what did he live? Answered Har: The next thing was that when the rime melted into drops, there was made thereof a cow, which hight Audhumbla. Four milk-streams ran from her teats, and she fed Ymer.','Rasmus B. Anderson',1880,'https://www.gutenberg.org/ebooks/18947',NULL,'primary-verbatim',NULL,true,'English translation (Anderson, The Younger Edda) located by name within the work (not exact chapter); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NOR_BRAGI_PROSE_','ENT_NOR_BRAGI','SRC_PROSE_EDDA','Snorri Sturluson, Prose Edda','Snorri Sturluson, Prose Edda','Brage is the name of another of the asas. He is famous for his wisdom, eloquence and flowing speech. He is a master-skald, and from him song-craft is called brag (poetry), and such men or women as distinguish themselves by their eloquence are called brag-men and brag-women. His wife is Idun.','Rasmus B. Anderson',1880,'https://www.gutenberg.org/ebooks/18947',NULL,'primary-verbatim',NULL,true,'English translation (Anderson, The Younger Edda) located by name within the work (not exact chapter); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NOR_FARBAUTI_PROSE_','ENT_NOR_FARBAUTI','SRC_PROSE_EDDA','Snorri Sturluson, Prose Edda','Snorri Sturluson, Prose Edda','His father is the giant Farbaute, but his mother''s name is Laufey, or Nal. His brothers are Byleist and Helblinde. Loke is fair and beautiful of face, but evil in disposition, and very fickle-minded. He surpasses other men in the craft called cunning, and cheats in all things. He has often brought the asas into great trouble, and often helped them out again, with his cunning contrivances. His wife hight Sygin, and their son, Nare, or Narfe. 34.','Rasmus B. Anderson',1880,'https://www.gutenberg.org/ebooks/18947',NULL,'primary-verbatim',NULL,true,'English translation (Anderson, The Younger Edda) located by name within the work (not exact chapter); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NOR_FJALAR_DWARF_PROSE_','ENT_NOR_FJALAR_DWARF','SRC_PROSE_EDDA','Snorri Sturluson, Prose Edda','Snorri Sturluson, Prose Edda','Once he came to the home of the dwarfs Fjalar and Galar. They called him aside, saying they wished to speak with him alone, slew him and let his blood run into two jars called Son and Bodn, and into a kettle called Odrarer. They mixed honey with the blood, and thus was produced such mead that whoever drinks from it becomes a skald and sage.','Rasmus B. Anderson',1880,'https://www.gutenberg.org/ebooks/18947',NULL,'primary-verbatim',NULL,true,'English translation (Anderson, The Younger Edda) located by name within the work (not exact chapter); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NOR_FORSETI_PROSE_','ENT_NOR_FORSETI','SRC_PROSE_EDDA','Snorri Sturluson, Prose Edda','Snorri Sturluson, Prose Edda','Forsete''s hall. GLOIN. A dwarf. GNA. Frigg''s messenger. GNIPA-CAVE. The cave before which the dog Garm barks. GNITA-HEATH. Fafner''s abode, where he kept the treasure of the Niblungs. GOIN. A serpent under Ygdrasil. GOL. A valkyrie. GOLDFAX. The giant Hrungner''s horse. GOMUL. One of the streams flowing from Hvergelmer. GONDLER. One of the names of Odin. GONDUL. A valkyrie. GOPUL. One of the streams flowing from Hvergelmer. GOT. A name of Odin. GOTE.','Rasmus B. Anderson',1880,'https://www.gutenberg.org/ebooks/18947',NULL,'primary-verbatim',NULL,true,'English translation (Anderson, The Younger Edda) located by name within the work (not exact chapter); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NOR_FULLA_PROSE_','ENT_NOR_FULLA','SRC_PROSE_EDDA','Snorri Sturluson, Prose Edda','Snorri Sturluson, Prose Edda','The fifth is Fulla, who is also a may, she wears her hair flowing and has a golden ribbon about her head; she carries Frigg''s chest, takes care of her shoes and knows her secrets. The sixth is Freyja, who is ranked with Frigg. She is wedded to the man whose name is Oder; their daughter''s name is Hnos, and she is so fair that all things fair and precious are called, from her name, Hnos. Oder went far away. Freyja weeps for him, but her tears are red gold.','Rasmus B. Anderson',1880,'https://www.gutenberg.org/ebooks/18947',NULL,'primary-verbatim',NULL,true,'English translation (Anderson, The Younger Edda) located by name within the work (not exact chapter); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NOR_GALAR_PROSE_','ENT_NOR_GALAR','SRC_PROSE_EDDA','Snorri Sturluson, Prose Edda','Snorri Sturluson, Prose Edda','Once he came to the home of the dwarfs Fjalar and Galar. They called him aside, saying they wished to speak with him alone, slew him and let his blood run into two jars called Son and Bodn, and into a kettle called Odrarer. They mixed honey with the blood, and thus was produced such mead that whoever drinks from it becomes a skald and sage.','Rasmus B. Anderson',1880,'https://www.gutenberg.org/ebooks/18947',NULL,'primary-verbatim',NULL,true,'English translation (Anderson, The Younger Edda) located by name within the work (not exact chapter); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NOR_GEFJON_PROSE_','ENT_NOR_GEFJON','SRC_PROSE_EDDA','Snorri Sturluson, Prose Edda','Snorri Sturluson, Prose Edda','Then he sent Gefjun across the sound to the north to discover new countries, and she came to King Gylfe, who gave her a ploughland. Then she went to Jotunheim and bore four sons to a giant, and transformed them into a yoke of oxen, and yoked them to a plough and broke out the land into the ocean, right opposite to Odinse, which was called Seeland, where she afterward settled and dwelt. Skjold, a son of Odin, married her, and they dwelt at Leidre.','Rasmus B. Anderson',1880,'https://www.gutenberg.org/ebooks/18947',NULL,'primary-verbatim',NULL,true,'English translation (Anderson, The Younger Edda) located by name within the work (not exact chapter); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NOR_HERMOD_PROSE_','ENT_NOR_HERMOD','SRC_PROSE_EDDA','Snorri Sturluson, Prose Edda','Snorri Sturluson, Prose Edda','esfet; his son Bedvig; his son Atra, whom we call Annan; his son Itrman; his son Heremod (Hermod); his son Skjaldun, whom we call Skjold; his son Bjaf, whom we call Bjar; his son Jat; his son Gudolf, his son Fjarlaf, whom we call Fridleif; he had the son who is called Vodin, whom we call Odin; he was a famous man for wisdom and all accomplishments. His wife hight Frigida, whom we call Frigg. 10.','Rasmus B. Anderson',1880,'https://www.gutenberg.org/ebooks/18947',NULL,'primary-verbatim',NULL,true,'English translation (Anderson, The Younger Edda) located by name within the work (not exact chapter); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NOR_HRUNGNIR_PROSE_','ENT_NOR_HRUNGNIR','SRC_PROSE_EDDA','Snorri Sturluson, Prose Edda','Snorri Sturluson, Prose Edda','They regarded it very important who should gain the victory, and they feared the worst from Thor if Hrungner should be defeated, for he was the strongest among them. Thereupon the giants made at Grjottungard a man of clay, who was nine rasts tall and three rasts broad under the arms, but being unable to find a heart large enough to be suitable for him, they took the heart from a mare, but even this fluttered and trembled when Thor came.','Rasmus B. Anderson',1880,'https://www.gutenberg.org/ebooks/18947',NULL,'primary-verbatim',NULL,true,'English translation (Anderson, The Younger Edda) located by name within the work (not exact chapter); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NOR_LAUFEY_PROSE_','ENT_NOR_LAUFEY','SRC_PROSE_EDDA','Snorri Sturluson, Prose Edda','Snorri Sturluson, Prose Edda','His father is the giant Farbaute, but his mother''s name is Laufey, or Nal. His brothers are Byleist and Helblinde. Loke is fair and beautiful of face, but evil in disposition, and very fickle-minded. He surpasses other men in the craft called cunning, and cheats in all things. He has often brought the asas into great trouble, and often helped them out again, with his cunning contrivances. His wife hight Sygin, and their son, Nare, or Narfe. 34.','Rasmus B. Anderson',1880,'https://www.gutenberg.org/ebooks/18947',NULL,'primary-verbatim',NULL,true,'English translation (Anderson, The Younger Edda) located by name within the work (not exact chapter); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NOR_MAGNI_PROSE_','ENT_NOR_MAGNI','SRC_PROSE_EDDA','Snorri Sturluson, Prose Edda','Snorri Sturluson, Prose Edda','Then came Magne, the son of Thor and Jarnsaxa. He was only three nights of age. He threw Hrungner''s foot off Thor, and said It was a great mishap, father, that I came so late. I think I could have slain this giant with my fist, had I met him. Then Thor arose, greeted his son lovingly, saying that he would become great and powerful; and, added he, I will give you the horse Goldfax, that belonged to Hrungner.','Rasmus B. Anderson',1880,'https://www.gutenberg.org/ebooks/18947',NULL,'primary-verbatim',NULL,true,'English translation (Anderson, The Younger Edda) located by name within the work (not exact chapter); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NOR_NANNA_PROSE_','ENT_NOR_NANNA','SRC_PROSE_EDDA','Snorri Sturluson, Prose Edda','Snorri Sturluson, Prose Edda','Balder''s corpse was borne out on the ship; and when his wife, Nanna, daughter of Nep, saw this, her heart was broken with grief and she died. She was borne to the funeral-pile and cast on the fire. Thor stood by and hallowed the pile with Mjolner. Before his feet ran a dwarf, whose name is Lit. Him Thor kicked with his foot and dashed him into the fire, and he, too, was burned. But this funeral-pile was attended by many kinds of folk.','Rasmus B. Anderson',1880,'https://www.gutenberg.org/ebooks/18947',NULL,'primary-verbatim',NULL,true,'English translation (Anderson, The Younger Edda) located by name within the work (not exact chapter); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NORR_ALFHEIM_PROSE_','ENT_NORR_ALFHEIM','SRC_PROSE_EDDA','Snorri Sturluson, Prose Edda','Snorri Sturluson, Prose Edda','One is there called Alfheim. There dwell the folk that are called light-elves; but the dark-elves dwell down in the earth, and they are unlike the light-elves in appearance, but much more so in deeds. The light-elves are fairer than the sun to look upon, but the dark-elves are blacker than pitch. Another place is called Breidablik, and no place is fairer.','Rasmus B. Anderson',1880,'https://www.gutenberg.org/ebooks/18947',NULL,'primary-verbatim',NULL,true,'English translation (Anderson, The Younger Edda) located by name within the work (not exact chapter); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NORR_ASGARD_PROSE_','ENT_NORR_ASGARD','SRC_PROSE_EDDA','Snorri Sturluson, Prose Edda','Snorri Sturluson, Prose Edda','In the next place, the sons of Bor made for themselves in the middle of the world a burg, which is called Asgard, and which we call Troy. There dwelt the gods and their race, and thence were wrought many tidings and adventures, both on earth and in the sky. In Asgard is a place called Hlidskjalf, and when Odin seated himself there in the high-seat, he saw over the whole world, and what every man was doing, and he knew all things that he saw.','Rasmus B. Anderson',1880,'https://www.gutenberg.org/ebooks/18947',NULL,'primary-verbatim',NULL,true,'English translation (Anderson, The Younger Edda) located by name within the work (not exact chapter); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NORR_BIFROST_PROSE_','ENT_NORR_BIFROST','SRC_PROSE_EDDA','Snorri Sturluson, Prose Edda','Snorri Sturluson, Prose Edda','Have you not been told that the gods made a bridge from earth to heaven, which is called Bifrost? You must have seen it. It may be that you call it the rainbow. It has three colors, is very strong, and is made with more craft and skill than other structures. Still, however strong it is, it will break when the sons of Muspel come to ride over it, and then they will have to swim their horses over great rivers in order to get on.','Rasmus B. Anderson',1880,'https://www.gutenberg.org/ebooks/18947',NULL,'primary-verbatim',NULL,true,'English translation (Anderson, The Younger Edda) located by name within the work (not exact chapter); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NORR_GINNUNGAGAP_PROSE_','ENT_NORR_GINNUNGAGAP','SRC_PROSE_EDDA','Snorri Sturluson, Prose Edda','Snorri Sturluson, Prose Edda','Added Thride: As cold and all things grim proceeded from Niflheim, so that which bordered on Muspelheim was hot and bright, and Ginungagap was as warm and mild as windless air. And when the heated blasts from Muspelheim met the rime, so that it melted into drops, then, by the might of him who sent the heat, the drops quickened into life and took the likeness of a man, who got the name Ymer. But the Frost giants call him Aurgelmer.','Rasmus B. Anderson',1880,'https://www.gutenberg.org/ebooks/18947',NULL,'primary-verbatim',NULL,true,'English translation (Anderson, The Younger Edda) located by name within the work (not exact chapter); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NORR_JOTUNHEIM_PROSE_','ENT_NORR_JOTUNHEIM','SRC_PROSE_EDDA','Snorri Sturluson, Prose Edda','Snorri Sturluson, Prose Edda','He left his goats there and went on his way east into Jotunheim, clear to the sea, and then he went on across the deep ocean, and went ashore on the other side, together with Loke and Thjalfe and Roskva. When they had proceeded a short distance, there stood before them a great wood, through which they kept going the whole day until dark. Thjalfe, who was of all men the fleetest of foot, bore Thor''s bag, but the wood was no good place for provisions.','Rasmus B. Anderson',1880,'https://www.gutenberg.org/ebooks/18947',NULL,'primary-verbatim',NULL,true,'English translation (Anderson, The Younger Edda) located by name within the work (not exact chapter); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NORR_MIDGARD_PROSE_','ENT_NORR_MIDGARD','SRC_PROSE_EDDA','Snorri Sturluson, Prose Edda','Snorri Sturluson, Prose Edda','From them all mankind is descended, and a dwelling-place was given them under Midgard. In the next place, the sons of Bor made for themselves in the middle of the world a burg, which is called Asgard, and which we call Troy. There dwelt the gods and their race, and thence were wrought many tidings and adventures, both on earth and in the sky.','Rasmus B. Anderson',1880,'https://www.gutenberg.org/ebooks/18947',NULL,'primary-verbatim',NULL,true,'English translation (Anderson, The Younger Edda) located by name within the work (not exact chapter); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NORR_MUSPELHEIM_PROSE_','ENT_NORR_MUSPELHEIM','SRC_PROSE_EDDA','Snorri Sturluson, Prose Edda','Snorri Sturluson, Prose Edda','But the south part of Ginungagap was lighted up by the glowing sparks that flew out of Muspelheim. Added Thride: As cold and all things grim proceeded from Niflheim, so that which bordered on Muspelheim was hot and bright, and Ginungagap was as warm and mild as windless air.','Rasmus B. Anderson',1880,'https://www.gutenberg.org/ebooks/18947',NULL,'primary-verbatim',NULL,true,'English translation (Anderson, The Younger Edda) located by name within the work (not exact chapter); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NORR_NIFLHEIM_PROSE_','ENT_NORR_NIFLHEIM','SRC_PROSE_EDDA','Snorri Sturluson, Prose Edda','Snorri Sturluson, Prose Edda','tyr moved upon the face of the deep, until the ice-cold rivers, the Elivogs, flowing from Niflheim, came in contact with the dazzling flames from Muspelheim. This was before Chaos. And Fimbultyr said: Let the melted drops of vapor quicken into life, and the giant Ymer was born in the midst of Ginungagap. He was not a god, but the father of all the race of evil giants. This was Chaos. And Fimbultyr said: Let Ymer be slain and let order be established.','Rasmus B. Anderson',1880,'https://www.gutenberg.org/ebooks/18947',NULL,'primary-verbatim',NULL,true,'English translation (Anderson, The Younger Edda) located by name within the work (not exact chapter); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NOR_SIGYN_PROSE_','ENT_NOR_SIGYN','SRC_PROSE_EDDA','Snorri Sturluson, Prose Edda','Snorri Sturluson, Prose Edda','But Sigyn, his wife, stands by him, and holds a dish under the venom-drops. Whenever the dish becomes full, she goes and pours away the venom, and meanwhile the venom drops onto Loke''s face. Then he twists his body so violently that the whole earth shakes, and this you call earthquakes. There he will lie bound until Ragnarok. CHAPTER XVI. RAGNAROK. 55. Then said Ganglere: What tidings are to be told of Ragnarok? Of this I have never heard before.','Rasmus B. Anderson',1880,'https://www.gutenberg.org/ebooks/18947',NULL,'primary-verbatim',NULL,true,'English translation (Anderson, The Younger Edda) located by name within the work (not exact chapter); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NOR_SINDRI_PROSE_','ENT_NOR_SINDRI','SRC_PROSE_EDDA','Snorri Sturluson, Prose Edda','Snorri Sturluson, Prose Edda','Thereupon Loke wagered his head with the dwarf, who hight Brok, that his brother Sindre would not be able to make three other treasures equally as good as these were. But when they came to the smithy, Sindre laid a pig-skin in the furnace and requested Brok to blow the bellows, and not to stop blowing before he (Sindre) had taken out of the furnace what he had put into it.','Rasmus B. Anderson',1880,'https://www.gutenberg.org/ebooks/18947',NULL,'primary-verbatim',NULL,true,'English translation (Anderson, The Younger Edda) located by name within the work (not exact chapter); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NOR_SKADI_PROSE_','ENT_NOR_SKADI','SRC_PROSE_EDDA','Snorri Sturluson, Prose Edda','Snorri Sturluson, Prose Edda','Njord took to wife Skade, a daughter of the giant Thjasse. She wished to live where her father had dwelt, that is, on the mountains in Thrymheim; Njord, on the other hand, preferred to be near the sea. They therefore agreed to pass nine nights in Thrymheim and three in Noatun.','Rasmus B. Anderson',1880,'https://www.gutenberg.org/ebooks/18947',NULL,'primary-verbatim',NULL,true,'English translation (Anderson, The Younger Edda) located by name within the work (not exact chapter); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NOR_THJAZI_PROSE_','ENT_NOR_THJAZI','SRC_PROSE_EDDA','Snorri Sturluson, Prose Edda','Snorri Sturluson, Prose Edda','Then came the giant Thjasse in the guise of an eagle, seized Idun and flew away with her to his home in Thrymheim. The asas were ill at ease on account of the disappearance of Idun,--they became gray-haired and old. They met in council and asked each other who last had seen Idun. The last that had been seen of her was that she had gone out of Asgard in company with Loke.','Rasmus B. Anderson',1880,'https://www.gutenberg.org/ebooks/18947',NULL,'primary-verbatim',NULL,true,'English translation (Anderson, The Younger Edda) located by name within the work (not exact chapter); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NOR_UTGARDALOKI_PROSE_','ENT_NOR_UTGARDALOKI','SRC_PROSE_EDDA','Snorri Sturluson, Prose Edda','Snorri Sturluson, Prose Edda','Thereupon they approached the king, Utgard-Loke, and greeted him. He scarcely deigned to look at them, smiled scornfully and showed his teeth, saying: It is late to ask for tidings of a long journey, but if I am not mistaken this stripling is Oku-Thor, is it not? It may be, however, that you are really bigger than you look For what feats are you and your companions prepared? No one can stay with us here, unless he is skilled in some craft or accomplishment','Rasmus B. Anderson',1880,'https://www.gutenberg.org/ebooks/18947',NULL,'primary-verbatim',NULL,true,'English translation (Anderson, The Younger Edda) located by name within the work (not exact chapter); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NOR_VIDAR_PROSE_','ENT_NOR_VIDAR','SRC_PROSE_EDDA','Snorri Sturluson, Prose Edda','Snorri Sturluson, Prose Edda','Vidar is the name of the silent asa. He has a very thick shoe, and he is the strongest next after Thor. From him the gods have much help in all hard tasks. 30. Ale, or Vale, is the son of Odin and Rind. He is daring in combat, and a good shot. 31. Uller is the name of one, who is a son of Sif, and a step-son of Thor. He is so good an archer, and so fast on his skees, that no one can contend with him.','Rasmus B. Anderson',1880,'https://www.gutenberg.org/ebooks/18947',NULL,'primary-verbatim',NULL,true,'English translation (Anderson, The Younger Edda) located by name within the work (not exact chapter); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1)
